<?php
namespace App\Services;use App\Enums\AgreementStatus;use App\Models\Agreement;use Dompdf\Dompdf;use Dompdf\Options;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\ValidationException;
class AgreementPdfService {public function generate(Agreement $agreement,int $actorId):Agreement{if(in_array($agreement->status,[AgreementStatus::Signed,AgreementStatus::Active,AgreementStatus::Expired,AgreementStatus::Cancelled]))throw ValidationException::withMessages(['pdf'=>'Final or closed agreements cannot be regenerated.']);$agreement->load(['service','dutyType','worker.verification']);$version=$agreement->pdf_version+1;$html=view('admin.agreements.document',['agreement'=>$agreement,'logoData'=>$this->dataUri($agreement->agency_logo_path),'customerSignature'=>$this->dataUri($agreement->customer_signature_path),'agencySignature'=>$this->dataUri($agreement->agency_signature_path),'agencyStamp'=>$this->dataUri($agreement->agency_stamp_path)])->render();$options=new Options();$options->set('defaultFont','DejaVu Sans');$options->set('isRemoteEnabled',false);$pdf=new Dompdf($options);$pdf->loadHtml($html,'UTF-8');$pdf->setPaper('A4','portrait');$pdf->render();$path="agreements/{$agreement->agreement_code}/agreement-v{$version}.pdf";Storage::disk('local')->put($path,$pdf->output());return DB::transaction(function()use($agreement,$actorId,$version,$path){$old=$agreement->status->value;$agreement->update(['pdf_path'=>$path,'pdf_version'=>$version,'pdf_generated_at'=>now(),'status'=>$old==='draft'?AgreementStatus::Generated:$agreement->status,'updated_by'=>$actorId]);$agreement->versions()->create(['version_number'=>$version,'snapshot_json'=>$agreement->fresh()->attributesToArray(),'pdf_path'=>$path,'created_by'=>$actorId]);if($old==='draft')$agreement->statusHistory()->create(['old_status'=>'draft','new_status'=>'generated','changed_by'=>$actorId,'reason'=>'PDF generated']);return $agreement->fresh();});}private function dataUri(?string $path):?string{if(!$path||!Storage::disk('local')->exists($path))return null;$mime=Storage::disk('local')->mimeType($path)?:'image/png';return 'data:'.$mime.';base64,'.base64_encode(Storage::disk('local')->get($path));}}
